"""Stateless document entry; not a sandbox or independent execution witness."""
import base64, datetime, hashlib, json, traceback
from pathlib import Path
from hermes_tools import write_file
BASE=Path('F:/ChnobelRuntime/review-journals/guard-policy-01-round04')
DRIVER=Path('F:/ChnobelRuntime/tooling/request-capture-02/driver.py')
DRIVER_SHA='57b23f362ec7793ab64a2a47d50b6161f4c8d9856feb265bb8c6335b414e09d2'
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def sha(raw):return hashlib.sha256(raw).hexdigest()
def binding(path):
    path=Path(path);raw=path.read_bytes();return {'path':path.as_posix(),'sha256':sha(raw),'bytes':len(raw)}
def save_new(path,value):
    if path.exists():raise FileExistsError('No overwrite or blind rerun: '+path.as_posix())
    text=json.dumps(value,ensure_ascii=False,indent=2)+'\n'
    result=write_file(path.as_posix(),text)
    if result.get('verified') is not True:raise RuntimeError({'writeRefused':result,'path':path.as_posix()})
    return binding(path)
def run(operation_path):
    op_path=Path(operation_path).resolve()
    assert op_path.parent.parent==BASE.resolve() and op_path.parent.name in {'preflight','redteam'}
    assert op_path.name.endswith('.operation.json') and len(op_path.name[:4])==4 and op_path.name[:4].isdigit()
    ident=op_path.name[:4];request_path=op_path.parent/(ident+'.entry-request.json');result_path=op_path.parent/(ident+'.entry-result.json')
    assert not request_path.exists() and not result_path.exists(),'Existing entry evidence; do not rerun this ID'
    raw=op_path.read_bytes()
    canonical="__import__('runpy').run_path('F:/ChnobelRuntime/tooling/request-capture-02/entry.py')['run']("+repr(op_path.as_posix())+")"
    request={'kind':'stateless-document-entry-request/2','id':ident,'preparedAt':now(),'operation':binding(op_path),'operationUtf8Raw':raw.decode('utf-8'),'entrySource':binding(__file__),'expectedDriver':{'path':DRIVER.as_posix(),'sha256':DRIVER_SHA},'canonicalControllerEntryCall':canonical,'scope':'Entry boundary only; host import/parse/path/acquisition failures before this request remain outside capture','persistentCaptureMappingRequired':False,'isProductExecution':False}
    request_binding=save_new(request_path,request)
    started=now();state='ENTRY_EXCEPTION';exception=None;response=None;actual_driver=None
    try:
        operation=json.loads(raw);assert operation['controllerEntryCall']==canonical
        driver_raw=DRIVER.read_bytes();actual_driver=binding(DRIVER);assert sha(driver_raw)==DRIVER_SHA
        namespace={'__file__':str(DRIVER),'__name__':'document_capture_02_isolated_call'}
        exec(compile(driver_raw,str(DRIVER),'exec'),namespace)
        response=namespace['run'](op_path.as_posix());state='DRIVER_RETURNED'
    except Exception:
        exception=traceback.format_exc()
    exception_raw=exception.encode('utf-8') if exception is not None else None
    present={}
    for suffix in ('request','result'):
        path=op_path.parent/(ident+'.'+suffix+'.json');present[suffix]=binding(path) if path.exists() else None
    result={'kind':'stateless-document-entry-result/2','id':ident,'request':request_binding,'startedAt':started,'finishedAt':now(),'state':state,'actualDriver':actual_driver,'driverResponse':response,'driverEvidenceAtReturn':present,'exception':None if exception_raw is None else {'utf8Raw':exception,'base64':base64.b64encode(exception_raw).decode('ascii'),'sha256':sha(exception_raw),'bytes':len(exception_raw)},'requestStillMatches':binding(request_path)==request_binding,'driverExitCode':response['exitCode'] if response is not None else None,'scope':'Actual entry exception and referenced process evidence; no raw host-tool response, crash durability or authentication claim','productExecution':'NOT_RUN'}
    result_binding=save_new(result_path,result)
    summary={'id':ident,'entryState':state,'entryRequest':request_binding,'entryResult':result_binding,'driverResponse':response,'exceptionRecorded':exception is not None}
    text=json.dumps(summary,ensure_ascii=False)
    if len(text.encode('utf-8'))>8000:text=json.dumps({'id':ident,'entryState':state,'entryRequest':request_binding,'entryResult':result_binding,'display':'WITHHELD; complete process streams and entry exception retained'},ensure_ascii=False)
    print(text)
